corrected_code:
router.post('/auth/refresh-reuse-alert', requireServiceAuth, async (req, res) => {
  const { compromisedTokenFamily } = req.body;

  const tokenRecord = await MongooseRefreshToken.findOne({ tokenFamily: compromisedTokenFamily });
  if (!tokenRecord) {
    return res.status(404).json({ error: 'Token family not found' });
  }

  await MongooseRefreshToken.updateMany(
    { user: tokenRecord.user },
    { $set: { isRevoked: true, revokeReason: 'TOKEN_REUSE_DETECTED' } }
  );

  res.json({ status: 'All user sessions terminated', userId: tokenRecord.user });
});
